CREATE TABLE IF NOT EXISTS gis_phase326_spatial_evidence (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),crosswalk_version text NOT NULL,source_feature_id uuid NOT NULL REFERENCES gis_spatial_features(id) ON DELETE CASCADE,target_feature_id uuid NOT NULL REFERENCES gis_spatial_features(id) ON DELETE CASCADE,source_provider text,target_provider text,source_area_name text,target_area_name text,source_state_code text,target_state_code text,source_geometry_valid boolean NOT NULL,target_geometry_valid boolean NOT NULL,source_area numeric,target_area numeric,intersection_area numeric,source_overlap_ratio numeric,target_overlap_ratio numeric,iou numeric,centroid_distance_km numeric,bbox_overlap numeric,name_similarity numeric,state_match boolean,spatial_score numeric,identity_score numeric,combined_score numeric,confidence text,decision text,source_geometry jsonb,target_geometry jsonb,evidence jsonb NOT NULL DEFAULT '{}'::jsonb,evidence_version text NOT NULL,algorithm_version text NOT NULL,geometry_crs text NOT NULL,geometry_corrections jsonb NOT NULL DEFAULT '[]'::jsonb,calculation_method text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(crosswalk_version,source_feature_id,target_feature_id));